<?php
require_once dirname(__DIR__,2).'/core/bootstrap.php';Auth::requireLogin();$db=Database::getInstance()->pdo();if($_SERVER['REQUEST_METHOD']==='POST'){Csrf::verify($_POST['csrf_token']??'');if(Auth::user()['role']!=='admin'){http_response_code(403);exit('غير مسموح');}$name=trim($_POST['name']);$price=(float)$_POST['price'];$cost=(float)$_POST['cost'];$cat=(int)$_POST['category_id'];if($name!==''&&$price>=0){$db->prepare('INSERT INTO products(name,category_id,cost,price) VALUES(?,?,?,?)')->execute(array($name,$cat?:null,$cost,$price));Helper::flash('تمت إضافة المنتج.','success');}Helper::redirect('modules/products/index.php');}$categories=$db->query('SELECT * FROM categories WHERE active=1')->fetchAll();$rows=$db->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();$pageTitle='المنتجات';require APP_ROOT.'/includes/header.php';?><div class="page-heading"><div><h1>المنتجات</h1><p>إدارة قائمة المنتجات وأسعارها</p></div></div><?php if(Auth::user()['role']==='admin'): ?><div class="card mb-3"><div class="card-header">إضافة منتج</div><div class="card-body"><form method="post" class="row g-3 align-items-end"><?= Helper::csrfField() ?><div class="col-md-4"><label class="form-label">اسم المنتج</label><input class="form-control" name="name" required></div><div class="col-md-2"><label class="form-label">سعر التكلفة</label><input class="form-control" name="cost" type="number" step="0.01" min="0" value="0"></div><div class="col-md-2"><label class="form-label">سعر البيع</label><input class="form-control" name="price" type="number" step="0.01" min="0" required></div><div class="col-md-2"><label class="form-label">الفئة</label><select name="category_id" class="form-select"><option value="0">بدون فئة</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>"><?= Helper::e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-coffee w-100">إضافة</button></div></form></div></div><?php endif; ?><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>المنتج</th><th>الفئة</th><th>التكلفة</th><th>سعر البيع</th><th>الحالة</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= Helper::e($r['name']) ?></td><td><?= Helper::e($r['category']?:'—') ?></td><td><?= Helper::money($r['cost']) ?></td><td class="fw-bold"><?= Helper::money($r['price']) ?></td><td><?= $r['active']?'نشط':'متوقف' ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require APP_ROOT.'/includes/footer.php';
